<?php
/** Web accessibility (WCAG): principles and laws, semantic HTML and alternatives, keyboard and focus, contrast, forms and testing, ARIA, page structure, WCAG 2.2, focus management, media and motion. */

return [
    'id' => 'a11y', 'family' => 'a11y', 'after' => 'html-base',
    'title' => L('Accessibilità web (WCAG)', 'Web Accessibility (WCAG)'), 'short' => L('Accessibilità', 'Accessibility'), 'level' => L('Base', 'Basics'),
    'desc' => L('Siti usabili da tutti: principi WCAG e leggi europee, HTML semantico e testi alternativi, tastiera e focus, contrasto, moduli accessibili, ARIA, le novità delle WCAG 2.2, finestre di dialogo, video e movimento, e come verificare.', 'Sites everyone can use: WCAG principles and European law, semantic HTML and alt text, keyboard and focus, contrast, accessible forms, ARIA, what is new in WCAG 2.2, dialogs, video and motion, and how to check.'),
    'lessons' => [
        lesson('why', L('Perché e per chi', 'Why and for whom'), [
            P('L’**accessibilità** significa che un sito funziona per tutti: chi non vede e usa uno **screen reader**, chi non usa il mouse, chi vede poco o non distingue i colori, chi ha difficoltà cognitive, ma anche chi ha il braccio ingessato o usa il telefono sotto il sole.', '**Accessibility** means a site works for everyone: people who are blind and use a **screen reader**, who do not use a mouse, who have low vision or colour blindness, who have cognitive difficulties, but also someone with a broken arm or using a phone in bright sunlight.'),
            P('Lo standard di riferimento sono le **WCAG** (Web Content Accessibility Guidelines), organizzate in quattro principi: **percepibile**, **utilizzabile**, **comprensibile**, **robusto**, con livelli A, AA e AAA. In Europa l’**European Accessibility Act**, applicato dal giugno 2025, rende obbligatoria l’accessibilità per molti servizi digitali come e-commerce e banche; in Italia anche la Legge Stanca per la pubblica amministrazione.', 'The reference standard is **WCAG** (Web Content Accessibility Guidelines), organised in four principles: **perceivable**, **operable**, **understandable**, **robust**, with levels A, AA and AAA. In Europe the **European Accessibility Act**, applied since June 2025, makes accessibility mandatory for many digital services such as e-commerce and banking; in Italy the Stanca Law also covers public administration.'),
        ], [
            Q('w1', L('Che cos’è uno screen reader?', 'What is a screen reader?'), [L('Un software che legge ad alta voce la pagina', 'Software reading the page aloud'), L('Un monitor speciale', 'A special monitor'), L('Un’estensione per i colori', 'A colour extension'), L('Un browser per bambini', 'A browser for children')], 0, L('Usato da chi non vede.', 'Used by blind people.')),
            Q('w2', L('Quali sono i quattro principi WCAG?', 'What are the four WCAG principles?'), [L('Percepibile, utilizzabile, comprensibile, robusto', 'Perceivable, operable, understandable, robust'), L('Veloce, bello, economico, nuovo', 'Fast, pretty, cheap, new'), L('Rosso, verde, blu, nero', 'Red, green, blue, black'), L('Nessuno', 'None')], 0, L('POUR in inglese.', 'POUR in English.')),
            Q('w3', L('Quale legge europea rende obbligatoria l’accessibilità per molti servizi digitali?', 'Which European law makes accessibility mandatory for many digital services?'), ['European Accessibility Act', 'GDPR', 'AI Act', 'Digital Markets Act'], 0, L('Applicata dal giugno 2025.', 'Applied since June 2025.')),
        ], task('text', L('Scrivi tre gruppi di persone che beneficiano di un sito accessibile, uno per riga con `-`, tra cui chi usa uno **screen reader** e chi usa solo la **tastiera**.', 'Write three groups of people who benefit from an accessible site, one per line with `-`, including **screen reader** users and **keyboard-only** users.'), "- \n- \n- ", [re('^-\s*\S.*\n-\s*\S.*\n-\s*\S', L('Tre gruppi', 'Three groups')), re('screen reader|lettore di schermo|non vedent|blind', L('Chi usa uno screen reader', 'Screen reader users')), re('tastiera|keyboard', L('Chi usa la tastiera', 'Keyboard users'))], '', "- persone non vedenti che usano uno screen reader\n- chi naviga solo con la tastiera\n- persone anziane che vedono poco"), [
            dMatch(pMatch(), [[L('Percepibile', 'Perceivable'), L('Si può vedere o sentire', 'Can be seen or heard')], [L('Utilizzabile', 'Operable'), L('Si usa con mouse e tastiera', 'Usable with mouse and keyboard')], [L('Comprensibile', 'Understandable'), L('Chiaro e prevedibile', 'Clear and predictable')], [L('Robusto', 'Robust'), L('Funziona con tecnologie diverse', 'Works with different technologies')]], L('I principi WCAG.', 'WCAG principles.')),
            dFlash(pFlash(), [[L('L’accessibilità aiuta anche chi ha disabilità temporanee', 'Accessibility also helps people with temporary disabilities'), true], [L('L’accessibilità riguarda solo chi non vede', 'Accessibility only concerns blind people'), false], [L('Le WCAG hanno livelli A, AA e AAA', 'WCAG has levels A, AA and AAA'), true], [L('In Europa l’accessibilità non è mai obbligatoria', 'In Europe accessibility is never mandatory'), false]], L('Un web per tutti.', 'A web for everyone.')),
        ]),
        lesson('semantic', L('HTML semantico e alternative', 'Semantic HTML and alternatives'), [
            P('La base dell’accessibilità è l’**HTML semantico**: usare l’elemento giusto per ogni cosa. Un `<button>` è raggiungibile con la tastiera e annunciato come pulsante; un `<div>` cliccabile no. Titoli `<h1>`…`<h6>` in ordine, liste, `<nav>`, `<main>` e `<footer>` permettono agli screen reader di orientarsi.', 'The basis of accessibility is **semantic HTML**: using the right element for each thing. A `<button>` is keyboard-reachable and announced as a button; a clickable `<div>` is not. Headings `<h1>`…`<h6>` in order, lists, `<nav>`, `<main>` and `<footer>` let screen readers find their way.'),
            C('<!-- ✗ -->
<div class="btn" onclick="salva()">Salva</div>
<img src="grafico.png">

<!-- ✓ -->
<button type="button" onclick="salva()">Salva</button>
<img src="grafico.png" alt="Vendite 2026: crescita del 15% rispetto al 2025">
<img src="decorazione.svg" alt="">', 'html'),
            P('Ogni immagine informativa ha un **testo alternativo** (`alt`) che ne descrive il contenuto o lo scopo; quelle solo decorative hanno `alt=""` così lo screen reader le salta. I video hanno **sottotitoli**, i link un testo che si capisce anche da solo (non “clicca qui”).', 'Every informative image has **alternative text** (`alt`) describing its content or purpose; purely decorative ones have `alt=""` so the screen reader skips them. Videos have **captions**, links have text that makes sense on its own (not “click here”).'),
        ], [
            Q('s1', L('Perché usare `<button>` invece di un `<div>` cliccabile?', 'Why use `<button>` instead of a clickable `<div>`?'), [L('È accessibile da tastiera e annunciato come pulsante', 'It is keyboard-accessible and announced as a button'), L('È più colorato', 'It is more colourful'), L('Non c’è differenza', 'There is no difference'), L('Il div è più veloce', 'The div is faster')], 0, L('Semantica gratis.', 'Free semantics.')),
            Q('s2', L('Che alt dare a un’immagine solo decorativa?', 'What alt should a purely decorative image get?'), [L('alt vuoto: alt=""', 'Empty alt: alt=""'), L('alt="immagine"', 'alt="image"'), L('Nessun attributo', 'No attribute'), L('Il nome del file', 'The file name')], 0, L('Lo screen reader la salta.', 'The screen reader skips it.')),
            Q('s3', L('Qual è un buon testo per un link?', 'What is good link text?'), [L('Scarica il listino prezzi 2026 (PDF)', 'Download the 2026 price list (PDF)'), L('Clicca qui', 'Click here'), L('Link', 'Link'), L('Qui', 'Here')], 0, L('Chiaro anche fuori contesto.', 'Clear even out of context.')),
        ], task('html', L('Correggi il codice: trasforma il `<div>` in un `<button type="button">` e aggiungi all’immagine `alt="Logo di Fucina"`.', 'Fix the code: turn the `<div>` into a `<button type="button">` and add `alt="Logo di Fucina"` to the image.'), "<img src=\"logo.png\">\n<div class=\"btn\" onclick=\"apri()\">Menu</div>", [has('button[type="button"]', L('C’è un pulsante vero', 'There is a real button'), 'Menu'), has('img[alt="Logo di Fucina"]', L('L’immagine ha il testo alternativo', 'The image has alt text')), re('(?<![\s\S])(?![\s\S]*<div[^>]*onclick)', L('Niente div cliccabili', 'No clickable divs'))], '', "<img src=\"logo.png\" alt=\"Logo di Fucina\">\n<button type=\"button\" class=\"btn\" onclick=\"apri()\">Menu</button>"), [
            dBug(pBug(), ['<h1>Corsi</h1>', '<h4>HTML</h4>', '<p>Impara le basi.</p>'], 1, '<h2>HTML</h2>', L('I titoli vanno in ordine, senza saltare livelli.', 'Headings go in order, without skipping levels.')),
            dMatch(pMatch(), [['alt', L('Testo alternativo', 'Alternative text')], ['alt=""', L('Immagine decorativa', 'Decorative image')], ['<button>', L('Azione accessibile', 'Accessible action')], ['<nav>', L('Navigazione', 'Navigation')], [L('Sottotitoli', 'Captions'), L('Video accessibili', 'Accessible videos')]], L('Semantica accessibile.', 'Accessible semantics.')),
        ]),
        lesson('keyboard', L('Tastiera, focus e contrasto', 'Keyboard, focus and contrast'), [
            P('Tutto deve funzionare **solo con la tastiera**: Tab per andare avanti, Maiusc+Tab per tornare, Invio e Spazio per attivare. Il **focus** deve essere sempre visibile: non togliere mai l’anello di focus con `outline: none` senza sostituirlo con uno stile ben evidente.', 'Everything must work **with the keyboard only**: Tab to go forward, Shift+Tab to go back, Enter and Space to activate. **Focus** must always be visible: never remove the focus ring with `outline: none` without replacing it with a clearly visible style.'),
            C('/* ✗ */
button:focus { outline: none; }

/* ✓ */
button:focus-visible {
  outline: 3px solid #1d4ed8;
  outline-offset: 2px;
}', 'css'),
            P('Il **contrasto** tra testo e sfondo deve essere almeno **4,5:1** per il testo normale e **3:1** per quello grande (livello AA). Non affidare un’informazione solo al colore: un campo con errore va segnalato anche con un’icona o un testo, non solo con il bordo rosso.', '**Contrast** between text and background must be at least **4.5:1** for normal text and **3:1** for large text (level AA). Do not convey information through colour alone: a field with an error must also be marked with an icon or text, not just a red border.'),
        ], [
            Q('k1', L('Quale tasto sposta il focus all’elemento successivo?', 'Which key moves focus to the next element?'), ['Tab', 'Esc', 'F5', 'Ctrl'], 0, L('Maiusc+Tab torna indietro.', 'Shift+Tab goes back.')),
            Q('k2', L('Qual è il contrasto minimo AA per il testo normale?', 'What is the minimum AA contrast for normal text?'), ['4,5:1', '1:1', '2:1', '10:1'], 0, L('3:1 per il testo grande.', '3:1 for large text.')),
            Q('k3', L('Perché non usare solo il colore per segnalare un errore?', 'Why not use colour alone to signal an error?'), [L('Chi non distingue i colori non lo vede', 'People with colour blindness miss it'), L('Il rosso è vietato', 'Red is forbidden'), L('Costa di più', 'It costs more'), L('Non c’è motivo', 'There is no reason')], 0, L('Aggiungi testo o icona.', 'Add text or an icon.')),
        ], task('css', L('Dai a tutti i link un focus ben visibile con `a:focus-visible` e `outline: 3px solid`.', 'Give all links a clearly visible focus with `a:focus-visible` and `outline: 3px solid`.'), "a {\n  color: #1d4ed8;\n}\n", [re('a:focus-visible\s*\{[^}]*outline\s*:\s*3px\s+solid', L('Focus visibile sui link', 'Visible focus on links'))], "<a href=\"#\">Corsi</a>", "a:focus-visible {\n  outline: 3px solid #1d4ed8;\n  outline-offset: 2px;\n}"), [
            dBug(pBug(), ['button {', '  background: #e5e7eb;', '}', 'button:focus {', '  outline: none;', '}'], 4, '  outline: 3px solid #1d4ed8;', L('Senza focus visibile chi usa la tastiera si perde.', 'Without visible focus keyboard users get lost.')),
            dFlash(pFlash(), [[L('Un sito deve funzionare solo con la tastiera', 'A site must work with the keyboard alone'), true], [L('outline: none senza alternative è una buona pratica', 'outline: none without an alternative is good practice'), false], [L('Il testo grande richiede almeno 3:1 di contrasto', 'Large text needs at least 3:1 contrast'), true], [L('Un bordo rosso basta a segnalare un errore', 'A red border alone signals an error'), false]], L('Visibile per tutti.', 'Visible to all.')),
        ]),
        lesson('forms', L('Moduli accessibili e verifiche', 'Accessible forms and checks'), [
            P('Ogni campo di un modulo ha un’**etichetta** collegata (`<label for>`), non solo un placeholder che sparisce mentre scrivi. Gli errori si spiegano a parole vicino al campo e si annunciano allo screen reader. **ARIA** (`aria-label`, `aria-describedby`, `aria-live`) aggiunge informazioni quando l’HTML non basta, ma la prima regola di ARIA è: se c’è un elemento HTML adatto, usa quello.', 'Every form field has a linked **label** (`<label for>`), not just a placeholder that vanishes while you type. Errors are explained in words near the field and announced to the screen reader. **ARIA** (`aria-label`, `aria-describedby`, `aria-live`) adds information when HTML is not enough, but the first rule of ARIA is: if a suitable HTML element exists, use it.'),
            C('<label for="email">Email</label>
<input id="email" type="email" autocomplete="email" required
       aria-describedby="email-errore" aria-invalid="true">
<p id="email-errore">Inserisci un indirizzo email valido, per esempio nome@dominio.it</p>

<button type="button" aria-label="Chiudi la finestra">✕</button>', 'html'),
            P('Per verificare: naviga il sito **solo con la tastiera**, prova uno **screen reader** (VoiceOver su Mac e iPhone, NVDA su Windows, TalkBack su Android), usa gli strumenti automatici come Lighthouse o axe. Gli strumenti automatici trovano solo una parte dei problemi: il test con persone vere resta il più prezioso.', 'To check: navigate the site **with the keyboard only**, try a **screen reader** (VoiceOver on Mac and iPhone, NVDA on Windows, TalkBack on Android), use automated tools like Lighthouse or axe. Automated tools find only some problems: testing with real people remains the most valuable.'),
        ], [
            Q('f1', L('Perché il placeholder non basta come etichetta?', 'Why is a placeholder not enough as a label?'), [L('Sparisce mentre scrivi e non sempre viene letto', 'It vanishes while typing and is not always read'), L('È troppo lungo', 'It is too long'), L('È vietato', 'It is forbidden'), L('Basta sempre', 'It is always enough')], 0, L('Serve un label collegato.', 'A linked label is needed.')),
            Q('f2', L('Qual è la prima regola di ARIA?', 'What is the first rule of ARIA?'), [L('Usa un elemento HTML adatto se esiste', 'Use a suitable HTML element if one exists'), L('Metti ARIA ovunque', 'Put ARIA everywhere'), L('Non usare mai HTML', 'Never use HTML'), L('ARIA sostituisce il CSS', 'ARIA replaces CSS')], 0, L('HTML prima di ARIA.', 'HTML before ARIA.')),
            Q('f3', L('Gli strumenti automatici trovano tutti i problemi di accessibilità?', 'Do automated tools find every accessibility problem?'), [L('No, solo una parte', 'No, only some'), L('Sì, tutti', 'Yes, all'), L('Solo quelli di colore', 'Only colour ones'), L('Nessuno', 'None')], 0, L('Servono anche prove manuali.', 'Manual tests are needed too.')),
        ], task('html', L('Aggiungi un’etichetta `<label for="nome">Nome</label>` collegata a un campo `<input id="nome" type="text" required>`.', 'Add a label `<label for="nome">Nome</label>` linked to a field `<input id="nome" type="text" required>`.'), "<form>\n  \n</form>", [has('label[for="nome"]', L('L’etichetta', 'The label'), 'Nome'), has('input#nome[type="text"][required]', L('Il campo collegato e obbligatorio', 'The linked, required field'))], '', "<label for=\"nome\">Nome</label>\n<input id=\"nome\" type=\"text\" required>"), [
            dMatch(pMatch(), [['<label for>', L('Etichetta collegata', 'Linked label')], ['aria-describedby', L('Collega una descrizione', 'Links a description')], ['aria-label', L('Nome accessibile', 'Accessible name')], ['aria-live', L('Annuncia i cambiamenti', 'Announces changes')], ['axe / Lighthouse', L('Verifiche automatiche', 'Automated checks')]], L('Moduli per tutti.', 'Forms for everyone.')),
            dFlash(pFlash(), [[L('Ogni campo dovrebbe avere un’etichetta', 'Every field should have a label'), true], [L('ARIA va usato al posto dell’HTML semantico', 'ARIA should replace semantic HTML'), false], [L('VoiceOver è uno screen reader', 'VoiceOver is a screen reader'), true], [L('Un punteggio Lighthouse di 100 garantisce un sito accessibile', 'A Lighthouse score of 100 guarantees an accessible site'), false]], L('Verificare davvero.', 'Really checking.')),
        ]),
        lesson('aria', L('ARIA, contenuti dinamici e lettori di schermo', 'ARIA, dynamic content and screen readers'), [
            P('La prima regola di **ARIA**: non usarla se un elemento HTML nativo fa già il lavoro (`<button>` invece di `<div role="button">`). ARIA serve per ciò che l’HTML non dice: lo stato di un menu (`aria-expanded`), un’etichetta per un pulsante con sola icona (`aria-label`), una zona che si aggiorna (`aria-live`).', 'The first rule of **ARIA**: do not use it if a native HTML element already does the job (`<button>` instead of `<div role="button">`). ARIA is for what HTML does not say: a menu’s state (`aria-expanded`), a label for an icon-only button (`aria-label`), a region that updates (`aria-live`).'),
            C('<button aria-expanded="false" aria-controls="menu">Menu</button>
<ul id="menu" hidden>…</ul>

<button aria-label="Chiudi"><svg aria-hidden="true">…</svg></button>

<p role="status" aria-live="polite">3 risultati trovati</p>', 'html'),
            P('Prova sempre con un **lettore di schermo** vero (VoiceOver su Mac e iPhone, NVDA su Windows, TalkBack su Android): ascolta se ogni controllo ha un nome, se l’ordine ha senso e se gli aggiornamenti vengono annunciati.', 'Always test with a real **screen reader** (VoiceOver on Mac and iPhone, NVDA on Windows, TalkBack on Android): listen whether every control has a name, whether the order makes sense and whether updates are announced.'),
        ], [
            Q('ar1', L('Qual è la prima regola di ARIA?', 'What is the first rule of ARIA?'), [L('Preferire l’HTML nativo', 'Prefer native HTML'), L('Usare ARIA ovunque', 'Use ARIA everywhere'), L('Mettere role su ogni div', 'Put role on every div'), L('Nascondere tutto ai lettori', 'Hide everything from readers')], 0, L('Un `<button>` vero fa già tutto.', 'A real `<button>` already does it all.')),
            Q('ar2', L('Che cosa annuncia `aria-live="polite"`?', 'What does `aria-live="polite"` announce?'), [L('Gli aggiornamenti della zona, senza interrompere', 'Updates to the region, without interrupting'), L('Solo gli errori', 'Only errors'), L('Niente', 'Nothing'), L('I titoli', 'Headings')], 0, L('Utile per i risultati di ricerca.', 'Useful for search results.')),
            Q('ar3', L('Come dai un nome a un pulsante con sola icona?', 'How do you name an icon-only button?'), ['aria-label', 'title soltanto', 'alt sul button', 'role="name"'], 0, L('E l’icona con `aria-hidden`.', 'And the icon with `aria-hidden`.')),
        ], task('html', L('Crea un `<button>` con `aria-label="Cerca"` e un paragrafo `<p>` con `aria-live="polite"`.', 'Create a `<button>` with `aria-label="Cerca"` and a `<p>` paragraph with `aria-live="polite"`.'), '', [has('button[aria-label="Cerca"]', L('Il pulsante ha un nome', 'The button has a name')), has('p[aria-live="polite"]', L('C’è la zona che si aggiorna', 'The live region is there'))], '', "<button aria-label=\"Cerca\"><svg aria-hidden=\"true\"></svg></button>\n<p aria-live=\"polite\"></p>"), [
            dMatch(pMatch(), [['aria-expanded', L('Menu aperto o chiuso', 'Menu open or closed')], ['aria-label', L('Nome accessibile', 'Accessible name')], ['aria-live', L('Annuncia gli aggiornamenti', 'Announces updates')], ['aria-hidden', L('Nasconde ai lettori', 'Hides from readers')], ['VoiceOver', L('Lettore di Apple', 'Apple’s reader')]], L('ARIA con giudizio.', 'ARIA with judgement.')),
            dFlash(pFlash(), [[L('Un button nativo è meglio di un div con role', 'A native button beats a div with role'), true], [L('Più ARIA rende sempre una pagina più accessibile', 'More ARIA always makes a page more accessible'), false], [L('aria-hidden toglie un elemento ai lettori di schermo', 'aria-hidden removes an element from screen readers'), true], [L('I lettori di schermo esistono solo su Windows', 'Screen readers exist only on Windows'), false]], L('Accessibilità dinamica.', 'Dynamic accessibility.')),
        ]),
        lesson('structure', L('Lingua, titoli e punti di riferimento', 'Language, titles and landmarks'), [
            P('Le basi che si dimenticano più spesso: `lang` su `<html>` dice allo screen reader con che voce e pronuncia leggere; un `<title>` diverso per ogni pagina dice dove sei; i **punti di riferimento** (`<header>`, `<nav>`, `<main>`, `<footer>`) permettono di saltare da una zona all’altra.', 'The basics most often forgotten: `lang` on `<html>` tells the screen reader which voice and pronunciation to use; a different `<title>` on every page tells you where you are; **landmarks** (`<header>`, `<nav>`, `<main>`, `<footer>`) let you jump from one area to another.'),
            C('<html lang="it">
<head>
  <title>Carrello (3 articoli) · Fucina</title>
</head>
<body>
  <a class="salta" href="#contenuto">Vai al contenuto</a>
  <header>…</header>
  <nav aria-label="Principale">…</nav>
  <main id="contenuto">
    <h1>Il tuo carrello</h1>
    <p>Spedizione in <span lang="en">express</span>.</p>
  </main>
</body>
</html>', 'html'),
            P('Il link **«Vai al contenuto»** è il primo elemento raggiungibile con Tab: chi usa la tastiera evita di attraversare tutto il menu a ogni pagina. Può restare nascosto finché non riceve il focus, ma allora deve comparire. Una parola in un’altra lingua si segna con `lang` sul suo elemento.', 'The **“Skip to content”** link is the first element reachable with Tab: keyboard users avoid going through the whole menu on every page. It can stay hidden until it gets focus, but then it must appear. A word in another language is marked with `lang` on its element.'),
        ], [
            Q('st1', L('A che cosa serve `lang="it"` su `<html>`?', 'What is `lang="it"` on `<html>` for?'), [L('A tradurre la pagina in automatico', 'To translate the page automatically'), L('A scegliere il carattere tipografico', 'To choose the typeface'), L('A far leggere il testo con la pronuncia giusta', 'To have the text read with the right pronunciation'), L('A migliorare la velocità', 'To improve speed')], 2, L('Senza, uno screen reader inglese leggerebbe l’italiano con l’accento sbagliato.', 'Without it, an English screen reader would read Italian with the wrong accent.')),
            Q('st2', L('Perché serve un link «Vai al contenuto»?', 'Why is a “Skip to content” link needed?'), [L('Per saltare il menu con la tastiera', 'To skip the menu with the keyboard'), L('Per migliorare la grafica', 'To improve the design'), L('Per tornare alla home', 'To go back home'), L('Per stampare la pagina', 'To print the page')], 0, L('Va messo per primo nella pagina.', 'It goes first on the page.')),
            Q('st3', L('Quale `<title>` è più utile?', 'Which `<title>` is most useful?'), ['Pagina', 'Home', 'Fucina', L('Carrello (3 articoli) · Fucina', 'Cart (3 items) · Fucina')], 3, L('Prima ciò che è specifico, poi il nome del sito.', 'First what is specific, then the site name.')),
        ], task('html', L('Aggiungi come primo elemento del `body` un link `href="#contenuto"` con il testo «Vai al contenuto» e dai al `main` l’`id="contenuto"`.', 'Add as the first element of the `body` a link `href="#contenuto"` with the text “Vai al contenuto” and give the `main` the `id="contenuto"`.'), "<body>\n  <nav>…</nav>\n  <main>\n    <h1>Corsi</h1>\n  </main>\n</body>", [has('body > a:first-child[href="#contenuto"]', L('Il link è il primo elemento', 'The link is the first element'), 'contenuto'), has('main#contenuto', L('Il `main` è la destinazione', 'The `main` is the target'))], '', "<body>\n  <a href=\"#contenuto\">Vai al contenuto</a>\n  <nav>…</nav>\n  <main id=\"contenuto\">\n    <h1>Corsi</h1>\n  </main>\n</body>"), [
            dMatch(pMatch(), [['lang', L('Lingua e pronuncia', 'Language and pronunciation')], ['<title>', L('Dove ti trovi', 'Where you are')], ['<main>', L('Il contenuto principale', 'The main content')], ['<nav>', L('La navigazione', 'Navigation')], [L('Vai al contenuto', 'Skip to content'), L('Salta il menu', 'Skips the menu')]], L('Una pagina che si capisce prima ancora di leggerla.', 'A page you understand before you even read it.')),
            dBug(pBug(), ['<!doctype html>', '<html>', '<head>', '  <title>Corsi · Fucina</title>', '</head>'], 1, '<html lang="it">', L('Senza `lang` lo screen reader non sa con che pronuncia leggere.', 'Without `lang` the screen reader does not know which pronunciation to use.')),
        ]),
        lesson('wcag22', L('Le novità delle WCAG 2.2', 'What is new in WCAG 2.2'), [
            P('Le **WCAG 2.2** (2023) aggiungono criteri pensati soprattutto per telefoni, persone con disabilità motorie e cognitive. **Dimensione del bersaglio** (AA): ciò che si tocca misura almeno 24×24 pixel CSS, o ha abbastanza spazio intorno. **Focus non nascosto** (AA): l’elemento con il focus non deve finire coperto da barre fisse o banner.', '**WCAG 2.2** (2023) adds criteria aimed above all at phones, people with motor and cognitive disabilities. **Target size** (AA): what you tap is at least 24×24 CSS pixels, or has enough space around it. **Focus not obscured** (AA): the focused element must not end up covered by sticky bars or banners.'),
            C('.icona-btn {
  min-width: 24px;   /* minimo AA; 44px è ancora meglio */
  min-height: 24px;
}
html {
  scroll-padding-top: 80px; /* il focus non finisce sotto la barra fissa */
}', 'css'),
            P('**Movimenti di trascinamento** (AA): ciò che si fa trascinando si deve poter fare anche con un tocco. **Autenticazione accessibile** (AA): niente prove di memoria o enigmi per entrare, e il copia-incolla della password deve funzionare. **Aiuto coerente** e **dati ridondanti** (A): l’aiuto sta sempre nello stesso posto e non si chiede due volte lo stesso dato.', '**Dragging movements** (AA): whatever is done by dragging must also be doable with a tap. **Accessible authentication** (AA): no memory tests or puzzles to log in, and pasting the password must work. **Consistent help** and **redundant entry** (A): help is always in the same place and the same data is not asked for twice.'),
        ], [
            Q('n1', L('Qual è la dimensione minima AA di un bersaglio nelle WCAG 2.2?', 'What is the minimum AA target size in WCAG 2.2?'), ['10×10px', '16×16px', '24×24px', '100×100px'], 2, L('Oppure abbastanza spazio libero intorno al bersaglio.', 'Or enough free space around the target.')),
            Q('n2', L('Che cosa chiede il criterio sui movimenti di trascinamento?', 'What does the dragging movements criterion ask for?'), [L('Di vietare il trascinamento', 'To ban dragging'), L('Un’alternativa con un semplice tocco o clic', 'An alternative with a simple tap or click'), L('Di trascinare solo in orizzontale', 'To drag only horizontally'), L('Di usare sempre il mouse', 'To always use a mouse')], 1, L('Non tutti riescono a tenere premuto e muovere insieme.', 'Not everyone can press and move at the same time.')),
            Q('n3', L('Che cosa vieta l’autenticazione accessibile?', 'What does accessible authentication forbid?'), [L('Le password lunghe', 'Long passwords'), L('Il login con l’email', 'Logging in with email'), L('I gestori di password', 'Password managers'), L('Prove di memoria o enigmi senza alternative', 'Memory tests or puzzles without alternatives')], 3, L('Incollare la password o usare un gestore deve essere possibile.', 'Pasting the password or using a manager must be possible.')),
        ], task('css', L('Dai a `.icona-btn` un `min-width` e un `min-height` di almeno `24px` (scrivi `24px` o più).', 'Give `.icona-btn` a `min-width` and a `min-height` of at least `24px` (write `24px` or more).'), ".icona-btn {\n  padding: 0;\n}", [re('min-width\s*:\s*(2[4-9]|[3-9]\d|\d{3,})px', L('Larga almeno 24px', 'At least 24px wide')), re('min-height\s*:\s*(2[4-9]|[3-9]\d|\d{3,})px', L('Alta almeno 24px', 'At least 24px tall'))], "<button class=\"icona-btn\" aria-label=\"Chiudi\">✕</button>", ".icona-btn {\n  padding: 0;\n  min-width: 44px;\n  min-height: 44px;\n}"), [
            dMatch(pMatch(), [[L('Dimensione del bersaglio', 'Target size'), L('Almeno 24×24 pixel', 'At least 24×24 pixels')], [L('Focus non nascosto', 'Focus not obscured'), L('Niente barre sopra il focus', 'No bars covering the focus')], [L('Trascinamento', 'Dragging'), L('Alternativa con un tocco', 'Alternative with a tap')], [L('Autenticazione accessibile', 'Accessible authentication'), L('Niente enigmi per entrare', 'No puzzles to log in')], [L('Dati ridondanti', 'Redundant entry'), L('Non chiedere due volte lo stesso dato', 'Do not ask for the same data twice')]], L('Criteri nati dall’uso quotidiano del web.', 'Criteria born from everyday web use.')),
            dFlash(pFlash(), [[L('Le WCAG 2.2 sono uscite nel 2023', 'WCAG 2.2 came out in 2023'), true], [L('Una barra fissa può coprire l’elemento con il focus senza problemi', 'A sticky bar may cover the focused element with no problem'), false], [L('Impedire di incollare la password ostacola l’accessibilità', 'Blocking password pasting harms accessibility'), true], [L('Un bersaglio di 12×12 pixel senza spazio intorno rispetta il livello AA', 'A 12×12 pixel target with no space around it meets level AA'), false]], L('Più spazio per le dita, meno fatica per la memoria.', 'More room for fingers, less strain on memory.')),
        ]),
        lesson('focus-management', L('Gestire il focus in finestre e menu', 'Managing focus in dialogs and menus'), [
            P('Quando si apre una finestra modale, il focus deve entrarci, restare dentro finché è aperta e tornare al pulsante di partenza quando si chiude. Il `<dialog>` aperto con `showModal()` (o con `command="show-modal"`) lo fa da solo, rende inerte il resto della pagina e si chiude con Esc.', 'When a modal window opens, focus must move into it, stay inside while it is open and go back to the button that opened it when it closes. A `<dialog>` opened with `showModal()` (or with `command="show-modal"`) does this by itself, makes the rest of the page inert and closes with Esc.'),
            C('<button id="apri" commandfor="conferma" command="show-modal">Elimina</button>

<dialog id="conferma" aria-labelledby="titolo-conferma">
  <h2 id="titolo-conferma">Eliminare il file?</h2>
  <button commandfor="conferma" command="close" autofocus>Annulla</button>
  <button>Elimina</button>
</dialog>

<div inert>Contenuto non raggiungibile</div>', 'html'),
            P('Per una finestra costruita a mano servono più attenzioni: `inert` sul resto della pagina la rende non raggiungibile né cliccabile, e alla chiusura bisogna riportare il focus con `.focus()`. Nei menu a tendina `aria-expanded` dice se sono aperti, ed Esc deve richiuderli.', 'A hand-built window needs more care: `inert` on the rest of the page makes it unreachable and unclickable, and on closing you must bring focus back with `.focus()`. In drop-down menus `aria-expanded` says whether they are open, and Esc must close them again.'),
            Tip('In una finestra di conferma, metti il focus iniziale sull’azione meno pericolosa, come «Annulla».', 'In a confirmation window, put the initial focus on the least dangerous action, like “Cancel”.'),
        ], [
            Q('fm1', L('Dove deve tornare il focus quando una modale si chiude?', 'Where should focus go when a modal closes?'), [L('In cima alla pagina', 'To the top of the page'), L('Sul pulsante che l’ha aperta', 'To the button that opened it'), L('Sull’ultimo link della pagina', 'To the last link on the page'), L('Da nessuna parte', 'Nowhere')], 1, L('Così chi usa la tastiera riprende da dove era.', 'So keyboard users carry on from where they were.')),
            Q('fm2', L('Che cosa fa l’attributo `inert`?', 'What does the `inert` attribute do?'), [L('Rende l’elemento più veloce', 'It makes the element faster'), L('Lo rende trasparente', 'It makes it transparent'), L('Rende il contenuto non raggiungibile né cliccabile', 'It makes the content unreachable and unclickable'), L('Blocca l’animazione', 'It stops the animation')], 2, L('Anche gli screen reader lo ignorano.', 'Screen readers ignore it too.')),
            Q('fm3', L('Quale tasto dovrebbe chiudere una modale o un menu aperto?', 'Which key should close an open modal or menu?'), ['Tab', 'Invio', 'Spazio', 'Esc'], 3, L('Il `<dialog>` modale lo gestisce da solo.', 'The modal `<dialog>` handles it by itself.')),
        ], task('html', L('Crea un `<dialog id="info">` con un pulsante che lo chiude (`commandfor="info"` e `command="close"`), e fuori un pulsante che lo apre con `command="show-modal"`.', 'Create a `<dialog id="info">` with a button that closes it (`commandfor="info"` and `command="close"`), and outside it a button that opens it with `command="show-modal"`.'), '', [has('button[commandfor="info"][command="show-modal"]', L('C’è il pulsante che apre', 'The opening button is there')), has('dialog#info button[commandfor="info"][command="close"]', L('Il dialogo ha il pulsante che chiude', 'The dialog has the closing button'))], '', "<button commandfor=\"info\" command=\"show-modal\">Info</button>\n<dialog id=\"info\">\n  <p>Fucina è gratis.</p>\n  <button commandfor=\"info\" command=\"close\">Chiudi</button>\n</dialog>"), [
            dOrder(pSort(), [L('Il pulsante apre la modale', 'The button opens the modal'), L('Il focus entra nella modale', 'Focus moves into the modal'), L('Tab resta dentro la modale', 'Tab stays inside the modal'), L('Esc chiude la modale', 'Esc closes the modal'), L('Il focus torna al pulsante', 'Focus returns to the button')], L('Il percorso del focus in una modale fatta bene.', 'The focus path in a well-made modal.')),
            dFlash(pFlash(), [[L('Un `<dialog>` aperto con `showModal()` si chiude con Esc', 'A `<dialog>` opened with `showModal()` closes with Esc'), true], [L('Con una modale aperta, Tab può finire sulla pagina dietro', 'With a modal open, Tab may land on the page behind'), false], [L('`inert` toglie un blocco anche agli screen reader', '`inert` removes a block from screen readers too'), true], [L('Dopo la chiusura il focus può restare perso', 'After closing, focus may stay lost'), false]], L('Il focus è il cursore di chi usa la tastiera: non perderlo mai.', 'Focus is the keyboard user’s cursor: never lose it.')),
        ]),
        lesson('media-motion', L('Video, audio e movimento', 'Video, audio and motion'), [
            P('Un video con parlato ha bisogno di **sottotitoli** per chi non sente, e di una **audiodescrizione** quando le informazioni importanti sono solo nelle immagini. Un podcast o un audio ha bisogno di una **trascrizione**. I sottotitoli si collegano con `<track>`.', 'A video with speech needs **captions** for people who cannot hear, and **audio description** when important information is only in the pictures. A podcast or audio clip needs a **transcript**. Captions are linked with `<track>`.'),
            C('<video controls>
  <source src="lezione.mp4" type="video/mp4">
  <track kind="captions" src="lezione-it.vtt" srclang="it" label="Italiano" default>
</video>
<a href="lezione-trascrizione.html">Leggi la trascrizione</a>', 'html'),
            P('Niente deve lampeggiare più di **tre volte al secondo**: può scatenare crisi epilettiche. Ciò che si muove da solo per più di cinque secondi (caroselli, animazioni) deve potersi mettere in pausa. Rispetta `prefers-reduced-motion` e non far partire l’audio da solo.', 'Nothing should flash more than **three times a second**: it can trigger seizures. Anything that moves by itself for more than five seconds (carousels, animations) must be pausable. Respect `prefers-reduced-motion` and do not start audio by itself.'),
        ], [
            Q('mm1', L('Di che cosa ha bisogno un podcast per essere accessibile?', 'What does a podcast need to be accessible?'), [L('Di una trascrizione', 'A transcript'), L('Di un volume più alto', 'A louder volume'), L('Di una copertina colorata', 'A colourful cover'), L('Di un player più grande', 'A bigger player')], 0, L('Chi non sente può leggere ciò che si dice.', 'People who cannot hear can read what is said.')),
            Q('mm2', L('Quante volte al secondo può lampeggiare al massimo un contenuto?', 'At most how many times a second may content flash?'), [L('Dieci', 'Ten'), L('Senza limiti, se è breve', 'No limit, if it is short'), L('Una sola volta al minuto', 'Only once a minute'), L('Tre', 'Three')], 3, L('Oltre, il rischio di crisi epilettiche cresce.', 'Beyond that, the risk of seizures grows.')),
            Q('mm3', L('Che cosa serve a un carosello che scorre da solo?', 'What does a self-scrolling carousel need?'), [L('Più immagini', 'More images'), L('Un comando per metterlo in pausa', 'A control to pause it'), L('Una velocità più alta', 'A higher speed'), L('Un audio di sottofondo', 'Background audio')], 1, L('Vale per tutto ciò che si muove da solo per più di cinque secondi.', 'This applies to anything moving by itself for more than five seconds.')),
        ], task('html', L('Aggiungi al video un `<track kind="captions">` con `src="lezione.vtt"` e `srclang="it"`.', 'Add to the video a `<track kind="captions">` with `src="lezione.vtt"` and `srclang="it"`.'), "<video controls src=\"lezione.mp4\">\n\n</video>", [has('video track[kind="captions"][src="lezione.vtt"]', L('Il video ha i sottotitoli', 'The video has captions')), has('video track[srclang="it"]', L('La lingua è indicata', 'The language is given'))], '', "<video controls src=\"lezione.mp4\">\n  <track kind=\"captions\" src=\"lezione.vtt\" srclang=\"it\" label=\"Italiano\">\n</video>"), [
            dMatch(pMatch(), [[L('Sottotitoli', 'Captions'), L('Per chi non sente', 'For people who cannot hear')], [L('Audiodescrizione', 'Audio description'), L('Per chi non vede le immagini', 'For people who cannot see the pictures')], [L('Trascrizione', 'Transcript'), L('Il testo di un audio', 'The text of an audio clip')], ['<track>', L('Collega i sottotitoli', 'Links captions')], ['prefers-reduced-motion', L('Meno movimento', 'Less motion')]], L('Ogni contenuto ha la sua alternativa.', 'Every kind of content has its alternative.')),
            dFlash(pFlash(), [[L('Un audio che parte da solo può coprire lo screen reader', 'Audio that starts by itself can drown out the screen reader'), true], [L('I sottotitoli servono solo ai video in lingua straniera', 'Captions are only for foreign-language videos'), false], [L('Un carosello automatico deve potersi fermare', 'An automatic carousel must be stoppable'), true], [L('Un lampeggio veloce è solo un problema estetico', 'Fast flashing is only an aesthetic problem'), false]], L('Contenuti ricchi, ma per tutti.', 'Rich content, but for everyone.')),
        ]),
    ],
];
